export const getEntity200ResponseIdentifiersItemRegExp = new RegExp("^sha256:v1:[0-9a-f]{64}$");
export const getEntity200ResponseIdentifiersMaxOne = 100;

export const getEntity200ResponseKindMax = 64;

export const getEntity200ResponseOneLineSummaryMax = 500;

export const getEntity200ResponseResourceRefsItemMax = 386;

export const getEntity200ResponseResourceRefsItemRegExp = new RegExp(
  "^[a-z][a-z0-9_-]{0,63}:[a-z][a-z0-9_-]{0,63}:[^\\x00-\\x1F\\x7F]{1,256}$",
);
export const getEntity200ResponseResourceRefsMax = 100;

export const GetEntity200Response = zod
  .strictObject({
    canonicalEntityId: zod
      .string()
      .min(getEntity200ResponseCanonicalEntityIdMin)
      .max(getEntity200ResponseCanonicalEntityIdMax)
      .regex(getEntity200ResponseCanonicalEntityIdRegExp)
      .optional()
      .describe("Canonical id for a durable merge tombstone."),
    displayName: zod
      .string()
      .min(1)
      .max(getEntity200ResponseDisplayNameMax)
      .describe("Bounded display name."),
    id: zod
      .string()
      .min(getEntity200ResponseIdMin)
      .max(getEntity200ResponseIdMax)
      .regex(getEntity200ResponseIdRegExp)
      .describe("Stable entity ULID."),
    identifiers: zod
      .record(
        zod.string(),
        zod
          .array(
            zod
              .string()
              .min(getEntity200ResponseIdentifiersItemMin)
              .max(getEntity200ResponseIdentifiersItemMax)
              .regex(getEntity200ResponseIdentifiersItemRegExp)
              .describe(
                "Versioned one-way identifier fingerprint. Raw domains, tax ids, emails, and other PII are rejected.",
              ),
          )
          .max(getEntity200ResponseIdentifiersMaxOne),
      )
      .optional(),
    kind: zod
      .string()
      .min(1)
      .max(getEntity200ResponseKindMax)
      .describe("Non-customer entity kind."),
    oneLineSummary: zod
      .string()
      .max(getEntity200ResponseOneLineSummaryMax)
      .optional()
      .describe("Bounded one-line summary."),
    resourceRefs: zod
      .array(
        zod
          .string()
          .max(getEntity200ResponseResourceRefsItemMax)
          .regex(getEntity200ResponseResourceRefsItemRegExp)
          .describe("Stable external product pointer."),
      )
      .max(getEntity200ResponseResourceRefsMax),
    status: zod.enum(["active", "merged", "archived"]).describe("Lifecycle status."),
    version: zod.int().min(1),
  })
  .describe(
    "Minimal org-scoped entity spine projection. Raw note bodies and mirrored payloads are forbidden.",
  );

export const GetEntity400Response = zod
  .strictObject({
    code: zod.string().describe("Stable machine-readable error code."),
    detail: zod.string().optional().describe("Human-readable error detail."),
    instance: zod.string().nullish().describe("Optional occurrence URI."),
    requestId: zod.string().nullish().describe("Request id emitted by the API middleware."),
    status: zod.int().describe("HTTP status code."),
    title: zod.string().describe("Short HTTP-status summary."),
    traceId: zod.string().nullish().describe("OpenTelemetry trace id when tracing is active."),
    type: zod.string().describe("Problem type URI."),
  })
  .describe(
    "RFC 9457 problem details returned by Solomon AI API handlers. code, requestId, and traceId are extension members.",
  );

