/**
 * Strict fixed allowlist. Unknown fields are rejected.
 * @summary Upsert entity projection
 */
export const putEntityPathIdMin = 26;
export const putEntityPathIdMax = 26;

export const putEntityPathIdRegExp = new RegExp("^[0-9A-HJKMNP-TV-Z]{26}$");

export const PutEntityParams = zod.object({
  id: zod
    .string()
    .min(putEntityPathIdMin)
    .max(putEntityPathIdMax)
    .regex(putEntityPathIdRegExp)
    .describe("Stable entity ULID."),
});

export const putEntityBodyDisplayNameMax = 200;

export const putEntityBodyIdMin = 26;
export const putEntityBodyIdMax = 26;

export const putEntityBodyIdRegExp = new RegExp("^[0-9A-HJKMNP-TV-Z]{26}$");
export const putEntityBodyIdentifiersItemMin = 74;
export const putEntityBodyIdentifiersItemMax = 74;

export const putEntityBodyIdentifiersItemRegExp = new RegExp("^sha256:v1:[0-9a-f]{64}$");
export const putEntityBodyIdentifiersMaxOne = 100;

export const putEntityBodyKindMax = 64;

export const putEntityBodyOneLineSummaryMax = 500;

export const putEntityBodyResourceRefsItemMax = 386;

export const putEntityBodyResourceRefsItemRegExp = new RegExp(
  "^[a-z][a-z0-9_-]{0,63}:[a-z][a-z0-9_-]{0,63}:[^\\x00-\\x1F\\x7F]{1,256}$",
);
export const putEntityBodyResourceRefsMax = 100;

export const PutEntityBody = zod
  .strictObject({
    displayName: zod.string().min(1).max(putEntityBodyDisplayNameMax),
    expectedVersion: zod.int().min(1).optional(),
    id: zod
      .string()
      .min(putEntityBodyIdMin)
      .max(putEntityBodyIdMax)
      .regex(putEntityBodyIdRegExp)
      .optional()
      .describe("Optional body copy of the path ULID."),
    identifiers: zod
      .record(
        zod.string(),
        zod
          .array(
            zod
              .string()
              .min(putEntityBodyIdentifiersItemMin)
              .max(putEntityBodyIdentifiersItemMax)
              .regex(putEntityBodyIdentifiersItemRegExp)
              .describe(
                "Versioned one-way identifier fingerprint. Raw domains, tax ids, emails, and other PII are rejected.",
              ),
          )
          .max(putEntityBodyIdentifiersMaxOne),
      )
      .optional(),
    kind: zod.string().min(1).max(putEntityBodyKindMax),
    oneLineSummary: zod.string().max(putEntityBodyOneLineSummaryMax).optional(),
    resourceRefs: zod
      .array(
        zod
          .string()
          .max(putEntityBodyResourceRefsItemMax)
          .regex(putEntityBodyResourceRefsItemRegExp)
          .describe("Stable external product pointer."),
      )
      .max(putEntityBodyResourceRefsMax)
      .optional(),
  })
  .describe(
    "Strict projection allowlist accepted by PUT. Unknown fields, raw identifiers, and note bodies are rejected.",
  );

